site.css:
/* HEADER */
.bd-panel {
padding-top: 80px;
}
.bd-panel > .bd-pin.is-top {
margin-bottom: 200px;
}
.sm-nav {
font-size: 13px;
line-height: 19px;
}
.sm-nav .sm-logo {
display: block;
margin-bottom: 26px;
font-size: 13px;
}
.sm-nav a {
display: table;
border-bottom: 1px solid transparent;
}
.sm-nav a.is-current,
.sm-nav a:hover {
border-bottom-color: currentColor;
}

/* TEXT */
.bd-text a {
border-bottom: 1px solid currentColor;
}
.bd-site .sm-meta {
font-size: 11px;
line-height: 16px;
}
.sm-meta a {
border-bottom: 0;
}

/* PULL QUOTE */
.bd-site .sm-pull {
margin: 0;
padding: 40px 46px;
font-size: 13px;
line-height: 19px;
text-align: center;
box-shadow: 0 24px 60px rgba(0, 0, 0, 0.09);
}

/* JOURNAL CARDS */
.sm-card {
display: block;
min-height: 120px;
padding: 18px;
background: #eeeeee;
border-bottom: 0;
}
.sm-card-t {
display: block;
font-size: 15px;
line-height: 22px;
}
.sm-card-m {
display: block;
margin-top: 12px;
font-size: 11px;
line-height: 16px;
}

/* CONTRIBUTORS */
.sm-who summary {
list-style: none;
cursor: pointer;
}
.sm-who summary::-webkit-details-marker {
display: none;
}
.sm-who summary::before {
content: "+";
display: inline-block;
width: 27px;
}
.sm-who[open] summary::before {
content: "—";
}
.sm-who ul {
margin-top: 18px;
padding-left: 6px;
}
.sm-who li {
line-height: 31px;
}

/* NEXT */
.bd-site .sm-next {
padding-top: 120px;
font-size: 11px;
text-align: center;
}
.sm-next a {
border-bottom: 0;
}

/* SHOP */
.bd-site .sm-product {
font-size: 11px;
line-height: 18px;
text-align: center;
}

/* MOBILE */
@media (max-width: 760px) {
.bd-panel {
padding-top: 32px;
}
.bd-panel > .bd-pin.is-top {
margin-bottom: 64px;
}
.bd-site .sm-pull {
padding: 28px 22px;
}
}

